1	import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
2	import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
3	import { logSystemError, errorToMessage, errorToStack } from "../_shared/logError.ts";
4	
5	function getAllowedOrigin(req: Request): string {
6	  const origin = req.headers.get("origin") || "";
7	  const allowed = ["https://rankora.co", "https://www.rankora.co", "http://localhost:8080", "http://localhost:5173"];
8	  return allowed.includes(origin) ? origin : "https://rankora.co";
9	}
10	
11	const baseCorsHeaders = {
12	  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
13	};
14	
15	interface SendEmailRequest {
16	  to: string;
17	  template_key: string;
18	  variables: Record<string, string>;
19	}
20	
21	/** Replace {{variable}} placeholders in a template string */
22	function renderTemplate(template: string, variables: Record<string, string>): string {
23	  return template.replace(/\{\{(\w+)\}\}/g, (_, key) => variables[key] ?? "");
24	}
25	
26	/** Send an email via Resend API */
27	async function sendViaResend(
28	  apiKey: string,
29	  from: { email: string; name: string },
30	  to: string,
31	  subject: string,
32	  htmlContent: string
33	): Promise<{ ok: boolean; status: number; body: string; errorMessage?: string }> {
34	  const res = await fetch("https://api.resend.com/emails", {
35	    method: "POST",
36	    headers: {
37	      "Authorization": `Bearer ${apiKey}`,
38	      "Content-Type": "application/json",
39	    },
40	    body: JSON.stringify({
41	      from: `${from.name} <${from.email}>`,
42	      to: [to],
43	      subject,
44	      html: htmlContent,
45	    }),
46	  });
47	
48	  const body = await res.text();
49	  let errorMessage: string | undefined;
50	
51	  if (!res.ok) {
52	    try {
53	      const parsed = JSON.parse(body);
54	      errorMessage = parsed.message || parsed.error?.message;
55	    } catch { /* ignore */ }
56	  }
57	
58	  return { ok: res.ok, status: res.status, body, errorMessage };
59	}
60	
61	serve(async (req) => {
62	  const corsHeaders = { ...baseCorsHeaders, "Access-Control-Allow-Origin": getAllowedOrigin(req) };
63	  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
64	
65	  const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
66	  const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
67	  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
68	
69	  try {
70	    const { to, template_key, variables } = (await req.json()) as SendEmailRequest;
71	
72	    if (!to || !template_key) {
73	      return new Response(JSON.stringify({ error: "Missing 'to' or 'template_key'" }), {
74	        status: 400,
75	        headers: { ...corsHeaders, "Content-Type": "application/json" },
76	      });
77	    }
78	
79	    // Load platform config for Resend credentials
80	    const { data: config, error: configError } = await supabase
81	      .from("platform_config")
82	      .select("resend_api_key, email_from_address, email_from_name, outbound_email_enabled, email_notify_ranking_complete, email_notify_resume_received, email_notify_bonus_credits")
83	      .limit(1)
84	      .single();
85	
86	    if (configError) throw new Error(`Config error: ${configError.message}`);
87	
88	    if (!config?.outbound_email_enabled) {
89	      return new Response(JSON.stringify({ error: "Outbound email is disabled", skipped: true }), {
90	        status: 200,
91	        headers: { ...corsHeaders, "Content-Type": "application/json" },
92	      });
93	    }
94	
95	    if (!config.resend_api_key) {
96	      return new Response(JSON.stringify({ error: "Resend API key not configured" }), {
97	        status: 400,
98	        headers: { ...corsHeaders, "Content-Type": "application/json" },
99	      });
100	    }
101	
102	    // Check per-template notification settings
103	    if (template_key === "ranking_complete" && !config.email_notify_ranking_complete) {
104	      return new Response(JSON.stringify({ skipped: true, reason: "Ranking complete notifications disabled" }), {
105	        status: 200,
106	        headers: { ...corsHeaders, "Content-Type": "application/json" },
107	      });
108	    }
109	    if (template_key === "resume_received" && !config.email_notify_resume_received) {
110	      return new Response(JSON.stringify({ skipped: true, reason: "Resume received notifications disabled" }), {
111	        status: 200,
112	        headers: { ...corsHeaders, "Content-Type": "application/json" },
113	      });
114	    }
115	    if (template_key === "bonus_credits_received" && !config.email_notify_bonus_credits) {
116	      return new Response(JSON.stringify({ skipped: true, reason: "Bonus credits notifications disabled" }), {
117	        status: 200,
118	        headers: { ...corsHeaders, "Content-Type": "application/json" },
119	      });
120	    }
121	
122	    // Load template
123	    const { data: template, error: tplError } = await supabase
124	      .from("email_templates")
125	      .select("subject, body_html")
126	      .eq("template_key", template_key)
127	      .single();
128	
129	    if (tplError || !template) {
130	      return new Response(JSON.stringify({ error: `Template '${template_key}' not found` }), {
131	        status: 404,
132	        headers: { ...corsHeaders, "Content-Type": "application/json" },
133	      });
134	    }
135	
136	    // Render template with variables
137	    const subject = renderTemplate(template.subject, variables);
138	    const htmlContent = renderTemplate(template.body_html, variables);
139	
140	    const fromEmail = config.email_from_address || "noreply@rankora.co";
141	    const fromName = config.email_from_name || "Rankora";
142	
143	    // Send via Resend
144	    const result = await sendViaResend(
145	      config.resend_api_key,
146	      { email: fromEmail, name: fromName },
147	      to,
148	      subject,
149	      htmlContent
150	    );
151	
152	    if (!result.ok) {
153	      const friendlyMessage = result.errorMessage || `Resend error (status ${result.status})`;
154	
155	      console.error("Resend error:", result.status, result.body);
156	      await logSystemError({
157	        function_name: "send-email",
158	        error_type: "RESEND_SEND_ERROR",
159	        severity: "warning",
160	        error_message: `Resend error: status=${result.status} body=${result.body}`,
161	      });
162	      return new Response(JSON.stringify({
163	        error: friendlyMessage,
164	      }), {
165	        status: 502,
166	        headers: { ...corsHeaders, "Content-Type": "application/json" },
167	      });
168	    }
169	
170	    return new Response(JSON.stringify({ success: true }), {
171	      status: 200,
172	      headers: { ...corsHeaders, "Content-Type": "application/json" },
173	    });
174	  } catch (err: unknown) {
175	    console.error("send-email error:", err);
176	    await logSystemError({
177	      function_name: "send-email",
178	      error_type: "EMAIL_SEND_ERROR",
179	      severity: "warning",
180	      error_message: errorToMessage(err),
181	      error_stack: errorToStack(err),
182	    });
183	    return new Response(JSON.stringify({ error: err instanceof Error ? err.message : String(err) }), {
184	      status: 500,
185	      headers: { ...corsHeaders, "Content-Type": "application/json" },
186	    });
187	  }
188	});
