316	// ── skeleton ──────────────────────────────────────────────────────────────────
317	
318	function TasksSkeleton() {
319	  return (
320	    <div className="space-y-3">
321	      {[1, 2, 3, 4].map((i) => (
322	        <div key={i} className="flex items-center gap-3 px-4 py-2.5">
