11	export interface EmailOutreachDialogProps {
12	  open: boolean;
13	  onOpenChange: (open: boolean) => void;
14	  candidateName: string;
15	  candidateEmail: string;
16	  jobTitle: string;
17	  matchScore: number;
18	  resumeId: string;
19	  jobId: string;
