22	function buildDefaultTemplate(candidateName: string, jobTitle: string, matchScore: number): string {
23	  return `Hi ${candidateName},\n\nWe reviewed your application for the ${jobTitle} position and were impressed with your profile (${matchScore}% match).\n\nWe'd love to discuss this opportunity further. Would you be available for a brief call this week?\n\nBest regards`;
24	}
25	
26	function buildDefaultSubject(jobTitle: string): string {
27	  return `Regarding Your Application – ${jobTitle}`;
28	}
29	
30	const EmailOutreachDialog = ({
31	  open,
32	  onOpenChange,
33	  candidateName,
34	  candidateEmail,
35	  jobTitle,
36	  matchScore,
37	  resumeId,
38	  jobId,
39	}: EmailOutreachDialogProps) => {
40	  const [subject, setSubject] = useState(() => buildDefaultSubject(jobTitle));
41	  const [bodyText, setBodyText] = useState(() =>
42	    buildDefaultTemplate(candidateName, jobTitle, matchScore)
43	  );
44	  const [isSending, setIsSending] = useState(false);
45	
46	  // Reset fields when the dialog opens with fresh values
47	  const handleOpenChange = (nextOpen: boolean) => {
48	    if (nextOpen) {
49	      setSubject(buildDefaultSubject(jobTitle));
50	      setBodyText(buildDefaultTemplate(candidateName, jobTitle, matchScore));
51	    }
52	    onOpenChange(nextOpen);
53	  };
54	
55	  const bodyHtml = bodyText.replace(/\n/g, "<br>");
56	
57	  const handleSend = async () => {
58	    if (!subject.trim()) {
59	      toast.error("Please enter a subject");
60	      return;
61	    }
62	    if (!bodyText.trim()) {
63	      toast.error("Please enter a message body");
64	      return;
65	    }
66	
67	    setIsSending(true);
68	    try {
69	      const { data, error } = await supabase.functions.invoke("send-candidate-email", {
70	        body: {
71	          resume_id: resumeId,
72	          job_id: jobId,
73	          to_email: candidateEmail,
74	          subject: subject.trim(),
75	          body_html: bodyHtml,
76	        },
77	      });
78	
79	      if (error) throw error;
80	
81	      if (data?.skipped) {
82	        toast.warning("Outbound email is currently disabled. Enable it in Admin > Email Settings.");
83	        return;
84	      }
85	
86	      if (data?.error) {
87	        throw new Error(data.error);
88	      }
89	
90	      toast.success(`Email sent to ${candidateName}`);
91	      onOpenChange(false);
92	    } catch (err: any) {
93	      toast.error(err?.message || "Failed to send email");
94	    } finally {
95	      setIsSending(false);
96	    }
97	  };
98	
99	  const mailtoHref = `mailto:${candidateEmail}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(bodyText)}`;
100	
101	  return (
102	    <Dialog open={open} onOpenChange={handleOpenChange}>
103	      <DialogContent className="sm:max-w-[540px]">
104	        <DialogHeader>
105	          <DialogTitle className="flex items-center gap-2">
106	            <Mail className="h-4 w-4" />
107	            Email {candidateName}
108	          </DialogTitle>
109	        </DialogHeader>
110	
111	        <div className="space-y-4 py-2">
112	          {/* To — read-only */}
113	          <div className="space-y-1.5">
114	            <Label htmlFor="outreach-to">To</Label>
115	            <Input
116	              id="outreach-to"
117	              value={candidateEmail}
118	              readOnly
119	              className="bg-muted text-muted-foreground cursor-not-allowed"
120	            />
121	          </div>
122	
123	          {/* Subject — editable */}
124	          <div className="space-y-1.5">
125	            <Label htmlFor="outreach-subject">Subject</Label>
126	            <Input
127	              id="outreach-subject"
128	              value={subject}
129	              onChange={(e) => setSubject(e.target.value)}
130	              placeholder="Email subject"
131	              disabled={isSending}
132	            />
133	          </div>
134	
135	          {/* Body — editable */}
136	          <div className="space-y-1.5">
137	            <Label htmlFor="outreach-body">Message</Label>
138	            <Textarea
139	              id="outreach-body"
140	              value={bodyText}
141	              onChange={(e) => setBodyText(e.target.value)}
142	              rows={8}
143	              placeholder="Email body"
144	              disabled={isSending}
145	              className="resize-none"
146	            />
147	          </div>
148	        </div>
149	
150	        <DialogFooter className="flex-col-reverse sm:flex-row gap-2">
151	          {/* Fallback: open in email client */}
152	          <Button
153	            variant="outline"
154	            size="sm"
155	            asChild
156	            className="gap-1.5"
157	          >
158	            <a href={mailtoHref} target="_blank" rel="noopener noreferrer">
159	              <ExternalLink className="h-3.5 w-3.5" />
160	              Open in Email Client
161	            </a>
162	          </Button>
163	
164	          <Button onClick={handleSend} disabled={isSending} className="gap-1.5">
165	            <Mail className="h-3.5 w-3.5" />
166	            {isSending ? "Sending..." : "Send Email"}
167	          </Button>
168	        </DialogFooter>
169	      </DialogContent>
170	    </Dialog>
171	  );
172	};
