-- Email Sequences — drip-campaign feature
-- Recruiters can create multi-step email sequences and enroll candidates

-- ─── Sequence template ───────────────────────────────────────────────────────

create table if not exists sequences (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid not null references auth.users(id) on delete cascade,
  team_id      uuid references teams(id) on delete set null,
  name         text not null,
  description  text,
  is_active    boolean not null default true,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

-- ─── Steps within a sequence ─────────────────────────────────────────────────

create table if not exists sequence_steps (
  id           uuid primary key default gen_random_uuid(),
  sequence_id  uuid not null references sequences(id) on delete cascade,
  step_order   int not null,        -- 1, 2, 3 ...
  day_offset   int not null default 0, -- days after enrollment
  subject      text not null,
  body         text not null,       -- supports {{variables}}
  created_at   timestamptz not null default now()
);

-- ─── Per-candidate enrollment in a sequence ──────────────────────────────────

create table if not exists sequence_enrollments (
  id           uuid primary key default gen_random_uuid(),
  sequence_id  uuid not null references sequences(id) on delete cascade,
  resume_id    uuid not null references resumes(id) on delete cascade,
  job_id       uuid not null references jobs(id) on delete cascade,
  enrolled_by  uuid not null references auth.users(id),
  status       text not null default 'active'
                 check (status in ('active','paused','completed','stopped')),
  enrolled_at  timestamptz not null default now(),
  completed_at timestamptz,
  unique (sequence_id, resume_id)
);

-- ─── Individual send records per step per enrollment ─────────────────────────

create table if not exists sequence_sends (
  id             uuid primary key default gen_random_uuid(),
  enrollment_id  uuid not null references sequence_enrollments(id) on delete cascade,
  step_id        uuid not null references sequence_steps(id) on delete cascade,
  scheduled_for  timestamptz not null,
  sent_at        timestamptz,
  status         text not null default 'pending'
                   check (status in ('pending','sent','failed','skipped')),
  error          text,
  resend_id      text,   -- Resend message ID
  created_at     timestamptz not null default now()
);

-- ─── Indexes ─────────────────────────────────────────────────────────────────

create index if not exists idx_sequence_sends_pending
  on sequence_sends (scheduled_for)
  where status = 'pending';

create index if not exists idx_sequence_enrollments_user
  on sequence_enrollments (enrolled_by);

create index if not exists idx_sequences_user
  on sequences (user_id);

create index if not exists idx_sequence_steps_seq
  on sequence_steps (sequence_id, step_order);

create index if not exists idx_sequence_enrollments_seq
  on sequence_enrollments (sequence_id);

create index if not exists idx_sequence_sends_enrollment
  on sequence_sends (enrollment_id);

-- ─── updated_at trigger for sequences ────────────────────────────────────────

create or replace function update_sequences_updated_at()
returns trigger language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

create trigger trg_sequences_updated_at
  before update on sequences
  for each row execute function update_sequences_updated_at();

-- ─── RLS ─────────────────────────────────────────────────────────────────────

alter table sequences           enable row level security;
alter table sequence_steps      enable row level security;
alter table sequence_enrollments enable row level security;
alter table sequence_sends      enable row level security;

-- sequences — users see own + team-shared sequences
create policy "sequences_select" on sequences
  for select using (
    user_id = auth.uid()
    or (
      team_id is not null
      and team_id in (
        select team_id from team_members where user_id = auth.uid()
      )
    )
  );

create policy "sequences_insert" on sequences
  for insert with check (user_id = auth.uid());

create policy "sequences_update" on sequences
  for update using (user_id = auth.uid());

create policy "sequences_delete" on sequences
  for delete using (user_id = auth.uid());

-- sequence_steps — visible via parent sequence
create policy "sequence_steps_select" on sequence_steps
  for select using (
    sequence_id in (select id from sequences)
  );

create policy "sequence_steps_all" on sequence_steps
  for all using (
    sequence_id in (select id from sequences where user_id = auth.uid())
  );

-- sequence_enrollments — users see/manage their own
create policy "enrollments_select" on sequence_enrollments
  for select using (enrolled_by = auth.uid());

create policy "enrollments_insert" on sequence_enrollments
  for insert with check (enrolled_by = auth.uid());

create policy "enrollments_update" on sequence_enrollments
  for update using (enrolled_by = auth.uid());

-- sequence_sends — visible via enrollment
create policy "sends_select" on sequence_sends
  for select using (
    enrollment_id in (
      select id from sequence_enrollments where enrolled_by = auth.uid()
    )
  );

-- ─── pg_cron schedule (every 5 minutes) ──────────────────────────────────────
-- NOTE: pg_cron extension must be enabled on the project.
-- The SUPABASE_URL and SERVICE_ROLE_KEY are injected by the pg_net/Supabase environment.
-- If pg_cron is not available, this schedule can be set up via Supabase Dashboard > Cron Jobs.

do $$
begin
  -- Only schedule if pg_cron extension exists
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule(
      'send-sequence-steps',
      '*/5 * * * *',
      $cron$
        select net.http_post(
          url := current_setting('app.supabase_url') || '/functions/v1/send-sequence-step',
          headers := jsonb_build_object(
            'Authorization', 'Bearer ' || current_setting('app.service_role_key'),
            'Content-Type', 'application/json'
          ),
          body := '{}'::jsonb
        );
      $cron$
    );
  end if;
exception
  when others then
    -- pg_cron not available — schedule via Supabase Dashboard instead
    null;
end;
$$;

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
import { logSystemError, errorToMessage, errorToStack } from "../_shared/logError.ts";

const ALLOWED_ORIGINS = [
  "https://rankora.co",
  "https://www.rankora.co",
  "http://localhost:8080",
  "http://localhost:5173",
];

function getCorsOrigin(req: Request): string {
  const origin = req.headers.get("origin") || "";
  return ALLOWED_ORIGINS.includes(origin) ? origin : ALLOWED_ORIGINS[0];
}

interface EnrollRequest {
  sequence_id: string;
  resume_ids: string[];
  job_id: string;
}

interface SequenceStep {
  id: string;
  day_offset: number;
  step_order: number;
  subject: string;
  body: string;
}

serve(async (req) => {
  const corsHeaders = {
    "Access-Control-Allow-Origin": getCorsOrigin(req),
    "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  };

  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  if (req.method !== "POST") {
    return new Response(JSON.stringify({ error: "Method not allowed" }), {
      status: 405,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }

  const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
  const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

  // Verify JWT
  const authHeader = req.headers.get("Authorization");
  if (!authHeader) {
    return new Response(JSON.stringify({ error: "Missing authorization header" }), {
      status: 401,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }

  const token = authHeader.replace("Bearer ", "");
  const { data: { user }, error: authError } = await supabase.auth.getUser(token);
  if (authError || !user) {
    return new Response(JSON.stringify({ error: "Unauthorized" }), {
      status: 401,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }

  try {
    const { sequence_id, resume_ids, job_id } = (await req.json()) as EnrollRequest;

    if (!sequence_id || !Array.isArray(resume_ids) || resume_ids.length === 0 || !job_id) {
      return new Response(
        JSON.stringify({ error: "Missing required fields: sequence_id, resume_ids, job_id" }),
        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Verify the sequence exists and is owned by or shared with the requesting user
    const { data: sequence, error: seqError } = await supabase
      .from("sequences")
      .select("id, is_active, user_id, team_id")
      .eq("id", sequence_id)
      .single();

    if (seqError || !sequence) {
      return new Response(JSON.stringify({ error: "Sequence not found" }), {
        status: 404,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    if (!sequence.is_active) {
      return new Response(JSON.stringify({ error: "Sequence is inactive" }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // Verify ownership / team membership
    let hasAccess = sequence.user_id === user.id;
    if (!hasAccess && sequence.team_id) {
      const { count } = await supabase
        .from("team_members")
        .select("*", { count: "exact", head: true })
        .eq("team_id", sequence.team_id)
        .eq("user_id", user.id);
      hasAccess = (count ?? 0) > 0;
    }

    if (!hasAccess) {
      return new Response(JSON.stringify({ error: "Forbidden" }), {
        status: 403,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // Fetch all steps for this sequence
    const { data: steps, error: stepsError } = await supabase
      .from("sequence_steps")
      .select("id, day_offset, step_order, subject, body")
      .eq("sequence_id", sequence_id)
      .order("step_order", { ascending: true });

    if (stepsError) throw new Error(`Failed to fetch steps: ${stepsError.message}`);
    if (!steps || steps.length === 0) {
      return new Response(JSON.stringify({ error: "Sequence has no steps" }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const now = new Date();
    let enrolledCount = 0;
    let skippedCount = 0;
    const errors: string[] = [];

    for (const resumeId of resume_ids) {
      try {
        // Upsert enrollment — skip if already enrolled (unique constraint)
        const { data: enrollment, error: enrollError } = await supabase
          .from("sequence_enrollments")
          .insert({
            sequence_id,
            resume_id: resumeId,
            job_id,
            enrolled_by: user.id,
            status: "active",
          })
          .select("id")
          .single();

        if (enrollError) {
          // Unique constraint violation = already enrolled
          if (enrollError.code === "23505") {
            skippedCount++;
            continue;
          }
          throw new Error(enrollError.message);
        }

        if (!enrollment) {
          skippedCount++;
          continue;
        }

        // Create send records for each step
        const sendRows = (steps as SequenceStep[]).map((step) => {
          const scheduledFor = new Date(now);
          scheduledFor.setDate(scheduledFor.getDate() + step.day_offset);
          return {
            enrollment_id: enrollment.id,
            step_id: step.id,
            scheduled_for: scheduledFor.toISOString(),
            status: "pending",
          };
        });

        const { error: sendsError } = await supabase
          .from("sequence_sends")
          .insert(sendRows);

        if (sendsError) throw new Error(`Failed to create sends: ${sendsError.message}`);

        enrolledCount++;
      } catch (err: unknown) {
        const msg = err instanceof Error ? err.message : String(err);
        errors.push(`resume ${resumeId}: ${msg}`);
        console.error(`Enrollment error for resume ${resumeId}:`, msg);
      }
    }

    return new Response(
      JSON.stringify({
        enrolled: enrolledCount,
        skipped: skippedCount,
        errors: errors.length > 0 ? errors : undefined,
        total_sends: enrolledCount * steps.length,
      }),
      { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  } catch (err: unknown) {
    console.error("enroll-in-sequence error:", err);
    await logSystemError({
      function_name: "enroll-in-sequence",
      error_type: "ENROLL_ERROR",
      severity: "error",
      error_message: errorToMessage(err),
      error_stack: errorToStack(err),
      user_id: null,
    });
    return new Response(
      JSON.stringify({ error: err instanceof Error ? err.message : String(err) }),
      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  }
});

/**
 * send-sequence-step
 *
 * Cron worker — invoked every 5 minutes via pg_cron or Supabase Dashboard Cron Jobs.
 * Picks up to 50 pending sequence_sends whose scheduled_for <= now(),
 * renders the step template with candidate variables, sends via Resend, and
 * updates send status.
 *
 * Variable support: {{candidate_name}}, {{job_title}}, {{recruiter_name}},
 *                   {{company}}, {{recruiter_email}}
 */

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
import { logSystemError, errorToMessage } from "../_shared/logError.ts";

const BATCH_LIMIT = 50;

/** Replace {{variable}} placeholders in a string */
function renderTemplate(template: string, vars: Record<string, string>): string {
  return template.replace(/\{\{(\w+)\}\}/g, (_, key) => vars[key] ?? "");
}

/** Send a single email via Resend */
async function sendViaResend(
  apiKey: string,
  from: { email: string; name: string },
  to: string,
  subject: string,
  htmlContent: string
): Promise<{ ok: boolean; resendId: string | null; errorMessage: string | null }> {
  const res = await fetch("https://api.resend.com/emails", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${apiKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      from: `${from.name} <${from.email}>`,
      to: [to],
      subject,
      html: htmlContent,
    }),
  });

  const body = await res.text();

  if (!res.ok) {
    let errorMessage = `Resend error status=${res.status}`;
    try {
      const parsed = JSON.parse(body);
      errorMessage = parsed.message || parsed.error?.message || errorMessage;
    } catch { /* ignore */ }
    return { ok: false, resendId: null, errorMessage };
  }

  let resendId: string | null = null;
  try {
    const parsed = JSON.parse(body);
    resendId = parsed.id ?? null;
  } catch { /* ignore */ }

  return { ok: true, resendId, errorMessage: null };
}

serve(async (req) => {
  // Only service-role calls (from cron) are expected — no CORS needed.
  // But still allow OPTIONS for safety.
  if (req.method === "OPTIONS") {
    return new Response(null, {
      headers: { "Access-Control-Allow-Headers": "authorization, content-type" },
    });
  }

  const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
  const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;

  // Allow invocation from cron (service role bearer) or directly with user JWT
  const authHeader = req.headers.get("Authorization") ?? "";
  const token = authHeader.replace("Bearer ", "");
  const expectedServiceToken = SUPABASE_SERVICE_ROLE_KEY;

  // Accept either service role key (cron) or any valid bearer — we use service role client throughout
  const isCronCall = token === expectedServiceToken;
  if (!isCronCall) {
    // Allow authenticated calls for manual triggering during development
    const supabaseCheck = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
    const { error } = await supabaseCheck.auth.getUser(token);
    if (error) {
      return new Response(JSON.stringify({ error: "Unauthorized" }), {
        status: 401,
        headers: { "Content-Type": "application/json" },
      });
    }
  }

  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

  try {
    // Load platform config once for all sends in this batch
    const { data: config, error: configError } = await supabase
      .from("platform_config")
      .select("resend_api_key, email_from_address, email_from_name, outbound_email_enabled")
      .limit(1)
      .single();

    if (configError) throw new Error(`Config error: ${configError.message}`);

    if (!config?.outbound_email_enabled || !config.resend_api_key) {
      return new Response(
        JSON.stringify({ skipped: true, reason: "Email disabled or Resend key missing" }),
        { status: 200, headers: { "Content-Type": "application/json" } }
      );
    }

    const fromEmail = config.email_from_address || "noreply@rankora.co";
    const fromName = config.email_from_name || "Rankora";

    // Fetch pending sends — join all needed data in one query chain
    const { data: pendingSends, error: fetchError } = await supabase
      .from("sequence_sends")
      .select(`
        id,
        scheduled_for,
        enrollment_id,
        step_id,
        sequence_steps (
          subject,
          body,
          step_order,
          sequence_id
        ),
        sequence_enrollments (
          id,
          status,
          resume_id,
          job_id,
          enrolled_by,
          resumes (
            candidate_name,
            candidate_email
          ),
          jobs (
            title
          ),
          profiles:enrolled_by (
            full_name,
            company_name
          )
        )
      `)
      .eq("status", "pending")
      .lte("scheduled_for", new Date().toISOString())
      .limit(BATCH_LIMIT);

    if (fetchError) throw new Error(`Fetch error: ${fetchError.message}`);
    if (!pendingSends || pendingSends.length === 0) {
      return new Response(
        JSON.stringify({ processed: 0, message: "No pending sends" }),
        { status: 200, headers: { "Content-Type": "application/json" } }
      );
    }

    let sent = 0;
    let failed = 0;
    let skipped = 0;

    for (const send of pendingSends) {
      const enrollment = send.sequence_enrollments as any;
      const step = send.sequence_steps as any;

      // Skip if enrollment is paused or stopped
      if (!enrollment || enrollment.status === "paused" || enrollment.status === "stopped") {
        await supabase
          .from("sequence_sends")
          .update({ status: "skipped", error: `Enrollment ${enrollment?.status ?? "missing"}` })
          .eq("id", send.id);
        skipped++;
        continue;
      }

      const resume = enrollment.resumes as any;
      const candidateEmail = resume?.candidate_email;

      if (!candidateEmail) {
        await supabase
          .from("sequence_sends")
          .update({ status: "skipped", error: "No candidate email" })
          .eq("id", send.id);
        skipped++;
        continue;
      }

      // Build template variables
      const recruiterProfile = enrollment.profiles as any;
      const variables: Record<string, string> = {
        candidate_name: resume?.candidate_name || "Candidate",
        job_title: enrollment.jobs?.title || "the position",
        recruiter_name: recruiterProfile?.full_name || fromName,
        company: recruiterProfile?.company_name || fromName,
        recruiter_email: fromEmail,
      };

      const subject = renderTemplate(step.subject, variables);
      // Convert newlines to <br> for HTML email, then render variables
      const bodyHtml = renderTemplate(
        step.body.replace(/\n/g, "<br>"),
        variables
      );

      try {
        const result = await sendViaResend(
          config.resend_api_key,
          { email: fromEmail, name: variables.recruiter_name || fromName },
          candidateEmail,
          subject,
          bodyHtml
        );

        if (result.ok) {
          await supabase
            .from("sequence_sends")
            .update({
              status: "sent",
              sent_at: new Date().toISOString(),
              resend_id: result.resendId,
              error: null,
            })
            .eq("id", send.id);
          sent++;
        } else {
          await supabase
            .from("sequence_sends")
            .update({ status: "failed", error: result.errorMessage })
            .eq("id", send.id);
          failed++;

          await logSystemError({
            function_name: "send-sequence-step",
            error_type: "RESEND_ERROR",
            severity: "warning",
            error_message: result.errorMessage ?? "Unknown Resend error",
            user_id: enrollment.enrolled_by,
          });
        }
      } catch (sendErr: unknown) {
        const msg = errorToMessage(sendErr);
        await supabase
          .from("sequence_sends")
          .update({ status: "failed", error: msg })
          .eq("id", send.id);
        failed++;
        console.error(`send-sequence-step send error for send ${send.id}:`, msg);
      }
    }

    // Mark completed enrollments (all sends done)
    // Find enrollments where all sends are no longer pending
    const enrollmentIds = [...new Set(pendingSends.map((s) => s.enrollment_id))];
    for (const enrollmentId of enrollmentIds) {
      const { count } = await supabase
        .from("sequence_sends")
        .select("*", { count: "exact", head: true })
        .eq("enrollment_id", enrollmentId)
        .eq("status", "pending");

      if ((count ?? 0) === 0) {
        await supabase
          .from("sequence_enrollments")
          .update({ status: "completed", completed_at: new Date().toISOString() })
          .eq("id", enrollmentId)
          .eq("status", "active");
      }
    }

    return new Response(
      JSON.stringify({ processed: pendingSends.length, sent, failed, skipped }),
      { status: 200, headers: { "Content-Type": "application/json" } }
    );
  } catch (err: unknown) {
    console.error("send-sequence-step error:", err);
    await logSystemError({
      function_name: "send-sequence-step",
      error_type: "CRON_ERROR",
      severity: "error",
      error_message: errorToMessage(err),
    });
    return new Response(
      JSON.stringify({ error: err instanceof Error ? err.message : String(err) }),
      { status: 500, headers: { "Content-Type": "application/json" } }
    );
  }
});

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";

// ─── Types ────────────────────────────────────────────────────────────────────

export interface SequenceStep {
  id: string;
  sequence_id: string;
  step_order: number;
  day_offset: number;
  subject: string;
  body: string;
  created_at: string;
}

export interface Sequence {
  id: string;
  user_id: string;
  team_id: string | null;
  name: string;
  description: string | null;
  is_active: boolean;
  created_at: string;
  updated_at: string;
  /** Joined steps — present in useSequence(id), not in useSequences() list */
  sequence_steps?: SequenceStep[];
  /** Enrollment count — present in enriched list */
  enrollment_count?: number;
}

export interface SequenceEnrollment {
  id: string;
  sequence_id: string;
  resume_id: string;
  job_id: string;
  enrolled_by: string;
  status: "active" | "paused" | "completed" | "stopped";
  enrolled_at: string;
  completed_at: string | null;
  /** Joined from resumes */
  candidate_name?: string | null;
  candidate_email?: string | null;
  /** Joined from jobs */
  job_title?: string | null;
  /** Send progress */
  sends?: SequenceSend[];
}

export interface SequenceSend {
  id: string;
  enrollment_id: string;
  step_id: string;
  scheduled_for: string;
  sent_at: string | null;
  status: "pending" | "sent" | "failed" | "skipped";
  error: string | null;
  resend_id: string | null;
  created_at: string;
}

export interface CreateSequenceInput {
  name: string;
  description?: string;
  team_id?: string | null;
}

export interface UpdateSequenceInput {
  id: string;
  name?: string;
  description?: string;
  is_active?: boolean;
  team_id?: string | null;
}

export interface CreateStepInput {
  sequence_id: string;
  step_order: number;
  day_offset: number;
  subject: string;
  body: string;
}

export interface UpdateStepInput {
  id: string;
  step_order?: number;
  day_offset?: number;
  subject?: string;
  body?: string;
}

// ─── Query Key Factory ────────────────────────────────────────────────────────

const qk = {
  sequences: () => ["sequences"] as const,
  sequence: (id: string) => ["sequences", id] as const,
  enrollments: (sequenceId?: string) =>
    sequenceId ? ["enrollments", sequenceId] : (["enrollments"] as const),
};

// ─── Hooks ────────────────────────────────────────────────────────────────────

/** List all sequences accessible to the current user (own + team-shared) */
export function useSequences() {
  const { user } = useAuth();

  return useQuery<Sequence[]>({
    queryKey: qk.sequences(),
    queryFn: async () => {
      const { data, error } = await (supabase as any)
        .from("sequences")
        .select(`
          id, user_id, team_id, name, description, is_active, created_at, updated_at,
          enrollment_count:sequence_enrollments(count)
        `)
        .order("created_at", { ascending: false });

      if (error) throw error;

      // Flatten enrollment count from [{count: N}] → number
      return (data ?? []).map((seq: any) => ({
        ...seq,
        enrollment_count: seq.enrollment_count?.[0]?.count ?? 0,
      }));
    },
    enabled: !!user,
    staleTime: 60_000,
  });
}

/** Single sequence with its steps */
export function useSequence(id: string | null) {
  const { user } = useAuth();

  return useQuery<Sequence | null>({
    queryKey: qk.sequence(id ?? "__none__"),
    queryFn: async () => {
      if (!id) return null;
      const { data, error } = await (supabase as any)
        .from("sequences")
        .select(`
          id, user_id, team_id, name, description, is_active, created_at, updated_at,
          sequence_steps (
            id, sequence_id, step_order, day_offset, subject, body, created_at
          )
        `)
        .eq("id", id)
        .single();

      if (error) throw error;

      return {
        ...data,
        sequence_steps: (data?.sequence_steps ?? []).sort(
          (a: SequenceStep, b: SequenceStep) => a.step_order - b.step_order
        ),
      };
    },
    enabled: !!user && !!id,
    staleTime: 60_000,
  });
}

/** Enrollments for a specific sequence, with candidate + send status */
export function useEnrollments(sequenceId: string | null) {
  const { user } = useAuth();

  return useQuery<SequenceEnrollment[]>({
    queryKey: qk.enrollments(sequenceId ?? undefined),
    queryFn: async () => {
      if (!sequenceId) return [];

      const { data, error } = await (supabase as any)
        .from("sequence_enrollments")
        .select(`
          id, sequence_id, resume_id, job_id, enrolled_by, status, enrolled_at, completed_at,
          resumes ( candidate_name, candidate_email ),
          jobs ( title ),
          sends:sequence_sends (
            id, enrollment_id, step_id, scheduled_for, sent_at, status, error, resend_id, created_at
          )
        `)
        .eq("sequence_id", sequenceId)
        .order("enrolled_at", { ascending: false });

      if (error) throw error;

      return (data ?? []).map((e: any) => ({
        ...e,
        candidate_name: e.resumes?.candidate_name ?? null,
        candidate_email: e.resumes?.candidate_email ?? null,
        job_title: e.jobs?.title ?? null,
        sends: e.sends ?? [],
      }));
    },
    enabled: !!user && !!sequenceId,
    staleTime: 30_000,
  });
}

// ─── Mutations ───────────────────────────────────────────────────────────────

export function useCreateSequence() {
  const { user } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (input: CreateSequenceInput): Promise<Sequence> => {
      const { data, error } = await (supabase as any)
        .from("sequences")
        .insert({ ...input, user_id: user!.id })
        .select()
        .single();
      if (error) throw error;
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: qk.sequences() });
    },
  });
}

export function useUpdateSequence() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({ id, ...updates }: UpdateSequenceInput): Promise<void> => {
      const { error } = await (supabase as any)
        .from("sequences")
        .update(updates)
        .eq("id", id);
      if (error) throw error;
    },
    onSuccess: (_data, variables) => {
      queryClient.invalidateQueries({ queryKey: qk.sequences() });
      queryClient.invalidateQueries({ queryKey: qk.sequence(variables.id) });
    },
  });
}

export function useDeleteSequence() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (id: string): Promise<void> => {
      const { error } = await (supabase as any)
        .from("sequences")
        .delete()
        .eq("id", id);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: qk.sequences() });
    },
  });
}

// ─── Step mutations ───────────────────────────────────────────────────────────

export function useAddSequenceStep() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (input: CreateStepInput): Promise<SequenceStep> => {
      const { data, error } = await (supabase as any)
        .from("sequence_steps")
        .insert(input)
        .select()
        .single();
      if (error) throw error;
      return data;
    },
    onSuccess: (_data, variables) => {
      queryClient.invalidateQueries({ queryKey: qk.sequence(variables.sequence_id) });
    },
  });
}

export function useUpdateSequenceStep() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({ id, ...updates }: UpdateStepInput & { sequence_id: string }): Promise<void> => {
      const { error } = await (supabase as any)
        .from("sequence_steps")
        .update(updates)
        .eq("id", id);
      if (error) throw error;
    },
    onSuccess: (_data, variables) => {
      queryClient.invalidateQueries({ queryKey: qk.sequence(variables.sequence_id) });
    },
  });
}

export function useDeleteSequenceStep() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({ id, sequence_id }: { id: string; sequence_id: string }): Promise<void> => {
      const { error } = await (supabase as any)
        .from("sequence_steps")
        .delete()
        .eq("id", id);
      if (error) throw error;
      void sequence_id; // used in onSuccess
    },
    onSuccess: (_data, variables) => {
      queryClient.invalidateQueries({ queryKey: qk.sequence(variables.sequence_id) });
    },
  });
}

// ─── Enrollment mutations ─────────────────────────────────────────────────────

/** Bulk enroll candidates in a sequence via Edge Function */
export function useEnrollCandidates() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({
      sequence_id,
      resume_ids,
      job_id,
    }: {
      sequence_id: string;
      resume_ids: string[];
      job_id: string;
    }): Promise<{ enrolled: number; skipped: number; total_sends: number }> => {
      const { data, error } = await supabase.functions.invoke("enroll-in-sequence", {
        body: { sequence_id, resume_ids, job_id },
      });
      if (error) throw error;
      if (data?.error) throw new Error(data.error);
      return data;
    },
    onSuccess: (_data, variables) => {
      queryClient.invalidateQueries({ queryKey: qk.enrollments(variables.sequence_id) });
      queryClient.invalidateQueries({ queryKey: qk.sequences() });
    },
  });
}

/** Update a single enrollment status (pause/stop/resume) */
export function useUpdateEnrollment() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({
      id,
      sequence_id,
      status,
    }: {
      id: string;
      sequence_id: string;
      status: SequenceEnrollment["status"];
    }): Promise<void> => {
      const { error } = await (supabase as any)
        .from("sequence_enrollments")
        .update({ status })
        .eq("id", id);
      if (error) throw error;
      void sequence_id;
    },
    onSuccess: (_data, variables) => {
      queryClient.invalidateQueries({ queryKey: qk.enrollments(variables.sequence_id) });
    },
  });
}

