            />
            <VariableChips onInsert={(t) => insertToken("subject", t)} />
          </div>

          {/* Body with preview */}
          <div className="space-y-1.5">
            <Tabs value={previewTab} onValueChange={(v) => setPreviewTab(v as "edit" | "preview")}>
              <div className="flex items-center justify-between mb-1.5">
                <Label className="text-xs">Email body</Label>
                <TabsList className="h-7">
                  <TabsTrigger value="edit" className="text-xs px-2 h-5">Edit</TabsTrigger>
                  <TabsTrigger value="preview" className="text-xs px-2 h-5">
                    <Eye className="h-3 w-3 mr-1" />
                    Preview
                  </TabsTrigger>
                </TabsList>
              </div>
              <TabsContent value="edit" className="mt-0">
                <Textarea
                  value={step.body}
                  onChange={(e) => onChange(index, "body", e.target.value)}
                  placeholder="Write your email message here. Use the variable chips above to personalize."
                  rows={6}
                  className="resize-none text-sm"
                />
                <div className="mt-1.5">
                  <VariableChips onInsert={(t) => insertToken("body", t)} />
                </div>
              </TabsContent>
              <TabsContent value="preview" className="mt-0">
                <div className="min-h-[144px] rounded-md border border-border bg-muted/20 p-3 text-sm whitespace-pre-wrap">
                  {previewBody || (
                    <span className="text-muted-foreground italic">No content yet</span>
                  )}
                </div>
              </TabsContent>
            </Tabs>
          </div>
        </div>
      )}
    </div>
  );
}

