interface SequenceBuilderProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /** If provided, we're editing an existing sequence; otherwise creating new */
  sequenceId?: string | null;
  onSaved?: (id: string) => void;
}

export function SequenceBuilder({
  open,
  onOpenChange,
  sequenceId,
  onSaved,
}: SequenceBuilderProps) {
  const isEditing = !!sequenceId;

  const { data: existing, isLoading: loadingExisting } = useSequence(
    open && isEditing ? sequenceId : null
  );

  const createSequence = useCreateSequence();
  const updateSequence = useUpdateSequence();
  const addStep = useAddSequenceStep();
  const updateStep = useUpdateSequenceStep();
  const deleteStep = useDeleteSequenceStep();

  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [steps, setSteps] = useState<LocalStep[]>([]);
  const [deletingIndex, setDeletingIndex] = useState<number | null>(null);
  const [isSaving, setIsSaving] = useState(false);

  // Populate form when editing
  useEffect(() => {
    if (open && isEditing && existing) {
      setName(existing.name);
      setDescription(existing.description ?? "");
      setSteps(
        (existing.sequence_steps ?? []).map((s: SequenceStep) => ({
          id: s.id,
          step_order: s.step_order,
          day_offset: s.day_offset,
          subject: s.subject,
          body: s.body,
        }))
      );
    }
  }, [open, isEditing, existing]);

  // Reset when creating new
  useEffect(() => {
    if (open && !isEditing) {
      setName("");
      setDescription("");
      setSteps([
        { step_order: 1, day_offset: 0, subject: "", body: "" },
      ]);
    }
  }, [open, isEditing]);

  function handleStepChange(index: number, field: keyof LocalStep, value: string | number) {
    setSteps((prev) => {
      const next = [...prev];
      next[index] = { ...next[index], [field]: value };
      return next;
    });
  }

  function handleAddStep() {
    const maxOffset = steps.reduce((m, s) => Math.max(m, s.day_offset), 0);
    setSteps((prev) => [
      ...prev,
      {
        step_order: prev.length + 1,
        day_offset: maxOffset + 3,
        subject: "",
        body: "",
      },
    ]);
  }

  function handleMoveStep(index: number, direction: "up" | "down") {
    setSteps((prev) => {
      const next = [...prev];
      const targetIndex = direction === "up" ? index - 1 : index + 1;
      if (targetIndex < 0 || targetIndex >= next.length) return prev;
      [next[index], next[targetIndex]] = [next[targetIndex], next[index]];
      // Re-number
      return next.map((s, i) => ({ ...s, step_order: i + 1 }));
    });
  }

  async function handleDeleteStep(index: number) {
    const step = steps[index];
    setDeletingIndex(index);
    try {
      if (step.id && sequenceId) {
        await deleteStep.mutateAsync({ id: step.id, sequence_id: sequenceId });
      }
      setSteps((prev) => {
        const next = prev.filter((_, i) => i !== index);
        return next.map((s, i) => ({ ...s, step_order: i + 1 }));
      });
    } catch {
      toast.error("Failed to delete step");
    } finally {
      setDeletingIndex(null);
    }
  }

  async function handleSave() {
    if (!name.trim()) {
      toast.error("Sequence name is required");
      return;
    }
    if (steps.length === 0) {
      toast.error("Add at least one step");
      return;
    }
    const invalidStep = steps.find((s) => !s.subject.trim() || !s.body.trim());
    if (invalidStep) {
      toast.error(`Step ${invalidStep.step_order}: subject and body are required`);
      return;
    }

    setIsSaving(true);
    try {
      let savedId: string;

      if (isEditing && sequenceId) {
        await updateSequence.mutateAsync({
          id: sequenceId,
          name: name.trim(),
          description: description.trim() || undefined,
        });
        savedId = sequenceId;

        // Upsert steps — update existing, insert new
        for (const step of steps) {
          if (step.id) {
            await updateStep.mutateAsync({
              id: step.id,
              sequence_id: sequenceId,
              step_order: step.step_order,
              day_offset: step.day_offset,
              subject: step.subject.trim(),
              body: step.body.trim(),
            });
          } else {
            await addStep.mutateAsync({
              sequence_id: sequenceId,
              step_order: step.step_order,
              day_offset: step.day_offset,
              subject: step.subject.trim(),
              body: step.body.trim(),
            });
          }
        }
      } else {
        const created = await createSequence.mutateAsync({
          name: name.trim(),
          description: description.trim() || undefined,
        });
        savedId = created.id;

        for (const step of steps) {
          await addStep.mutateAsync({
            sequence_id: savedId,
            step_order: step.step_order,
            day_offset: step.day_offset,
            subject: step.subject.trim(),
            body: step.body.trim(),
          });
        }
      }

      toast.success(isEditing ? "Sequence updated" : "Sequence created");
      onSaved?.(savedId);
      onOpenChange(false);
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : "Failed to save sequence");
    } finally {
      setIsSaving(false);
    }
  }

  const isLoading = isEditing && loadingExisting;

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-2xl max-h-[90vh] overflow-hidden flex flex-col">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Mail className="h-4 w-4" />
            {isEditing ? "Edit Sequence" : "New Email Sequence"}
          </DialogTitle>
        </DialogHeader>

        {isLoading ? (
          <div className="flex items-center justify-center py-12">
            <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
          </div>
        ) : (
          <div className="flex-1 overflow-y-auto space-y-5 py-2 pr-1">
            {/* Name + description */}
            <div className="space-y-3">
              <div className="space-y-1.5">
                <Label htmlFor="seq-name">
                  Name <span className="text-destructive">*</span>
                </Label>
                <Input
                  id="seq-name"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  placeholder="e.g. Engineering candidate outreach"
                  disabled={isSaving}
                />
              </div>
              <div className="space-y-1.5">
                <Label htmlFor="seq-desc">Description</Label>
                <Textarea
                  id="seq-desc"
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  placeholder="Optional — helps your team understand the purpose"
                  rows={2}
                  className="resize-none text-sm"
                  disabled={isSaving}
                />
              </div>
            </div>

            <Separator />

            {/* Steps */}
            <div className="space-y-3">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm font-medium">Email Steps</p>
                  <p className="text-xs text-muted-foreground">
                    Define the sequence of emails. Day 0 sends immediately on enrollment.
                  </p>
                </div>
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={handleAddStep}
                  className="gap-1.5 shrink-0"
                  disabled={isSaving}
                >
                  <Plus className="h-3.5 w-3.5" />
                  Add Step
                </Button>
              </div>

              {steps.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-8 rounded-lg border-2 border-dashed border-border text-center">
                  <Mail className="h-8 w-8 text-muted-foreground/30 mb-2" />
                  <p className="text-sm text-muted-foreground">No steps yet</p>
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    onClick={handleAddStep}
                    className="mt-2 gap-1.5"
                  >
                    <Plus className="h-3.5 w-3.5" />
                    Add first step
                  </Button>
                </div>
              ) : (
                <div className="space-y-2">
                  {steps.map((step, i) => (
                    <StepEditor
                      key={step.id ?? `new-${i}`}
                      step={step}
                      index={i}
                      totalSteps={steps.length}
                      onChange={handleStepChange}
                      onDelete={handleDeleteStep}
                      onMoveUp={(idx) => handleMoveStep(idx, "up")}
                      onMoveDown={(idx) => handleMoveStep(idx, "down")}
                      isDeleting={deletingIndex === i}
                    />
                  ))}
                </div>
              )}
            </div>
          </div>
        )}

        <DialogFooter className="pt-2 gap-2">
          <Button
            variant="outline"
            onClick={() => onOpenChange(false)}
            disabled={isSaving}
          >
            Cancel
          </Button>
          <Button onClick={handleSave} disabled={isSaving || isLoading} className="gap-1.5">
            {isSaving && <Loader2 className="h-4 w-4 animate-spin" />}
            {isSaving ? "Saving…" : isEditing ? "Update Sequence" : "Create Sequence"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

