/**
 * EnrollInSequenceDialog
 *
 * Opened from JobDetailView bulk actions toolbar.
 * Lets the recruiter pick an active sequence and enroll the selected candidates.
 */

import { useState } from "react";
import { toast } from "sonner";
import { Mail, Loader2, Users, AlertCircle, Plus } from "lucide-react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import {
  useSequences,
  useSequence,
  useEnrollCandidates,
} from "@/hooks/useSequences";
import { SequenceBuilder } from "@/components/SequenceBuilder";

interface EnrollInSequenceDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  selectedResumeIds: string[];
  jobId: string;
}

export function EnrollInSequenceDialog({
  open,
  onOpenChange,
  selectedResumeIds,
  jobId,
}: EnrollInSequenceDialogProps) {
  const [selectedSequenceId, setSelectedSequenceId] = useState<string>("");
  const [builderOpen, setBuilderOpen] = useState(false);

  const { data: sequences = [], isLoading: loadingSequences } = useSequences();
  const { data: selectedSequence } = useSequence(selectedSequenceId || null);
  const enroll = useEnrollCandidates();

  const activeSequences = sequences.filter((s) => s.is_active);
  const stepCount = selectedSequence?.sequence_steps?.length ?? 0;
  const totalSends = selectedResumeIds.length * stepCount;

  async function handleEnroll() {
    if (!selectedSequenceId) {
      toast.error("Please select a sequence");
      return;
    }

    try {
      const result = await enroll.mutateAsync({
        sequence_id: selectedSequenceId,
        resume_ids: selectedResumeIds,
        job_id: jobId,
      });

      const parts: string[] = [];
      if (result.enrolled > 0)
        parts.push(`${result.enrolled} candidate${result.enrolled === 1 ? "" : "s"} enrolled`);
      if (result.skipped > 0)
        parts.push(`${result.skipped} already enrolled (skipped)`);

      toast.success(parts.join(", ") || "Enrollment complete");
      onOpenChange(false);
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : "Enrollment failed");
    }
  }

  return (
    <>
      <Dialog open={open} onOpenChange={onOpenChange}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Mail className="h-4 w-4" />
              Add to Email Sequence
            </DialogTitle>
            <DialogDescription>
              Enroll{" "}
              <span className="font-medium text-foreground">
                {selectedResumeIds.length} candidate
                {selectedResumeIds.length === 1 ? "" : "s"}
              </span>{" "}
              in an automated drip-email sequence.
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4 py-2">
            {/* Candidate count */}
            <div className="flex items-center gap-2 rounded-lg border border-border bg-muted/30 px-3 py-2.5">
              <Users className="h-4 w-4 text-muted-foreground shrink-0" />
              <div className="text-sm">
                <span className="font-medium">{selectedResumeIds.length}</span>
                <span className="text-muted-foreground">
                  {" "}candidate{selectedResumeIds.length === 1 ? "" : "s"} selected
                </span>
              </div>
            </div>

            {/* Sequence picker */}
            <div className="space-y-1.5">
              <Label htmlFor="sequence-select">Select Sequence</Label>

              {loadingSequences ? (
                <Skeleton className="h-9 w-full" />
              ) : activeSequences.length === 0 ? (
                <div className="flex flex-col items-center gap-3 rounded-lg border-2 border-dashed border-border py-6 text-center">
                  <AlertCircle className="h-6 w-6 text-muted-foreground/50" />
                  <div>
                    <p className="text-sm font-medium">No active sequences</p>
                    <p className="text-xs text-muted-foreground mt-0.5">
                      Create your first sequence to start automating outreach
                    </p>
                  </div>
                  <Button
                    size="sm"
                    variant="outline"
                    onClick={() => setBuilderOpen(true)}
                    className="gap-1.5"
                  >
                    <Plus className="h-3.5 w-3.5" />
                    Create Sequence
                  </Button>
                </div>
              ) : (
                <Select
                  value={selectedSequenceId}
                  onValueChange={setSelectedSequenceId}
                  disabled={enroll.isPending}
                >
                  <SelectTrigger id="sequence-select">
                    <SelectValue placeholder="Choose a sequence…" />
                  </SelectTrigger>
                  <SelectContent>
                    {activeSequences.map((seq) => (
                      <SelectItem key={seq.id} value={seq.id}>
                        <div className="flex items-center gap-2">
                          <span>{seq.name}</span>
                          {seq.enrollment_count !== undefined && (
                            <Badge
                              variant="secondary"
                              className="text-[10px] h-4 px-1 ml-1"
                            >
                              {seq.enrollment_count} enrolled
                            </Badge>
                          )}
                        </div>
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              )}

              {activeSequences.length > 0 && (
                <button
                  type="button"
                  onClick={() => setBuilderOpen(true)}
                  className="text-xs text-primary hover:underline mt-1"
                >
                  + Create new sequence
                </button>
              )}
            </div>

            {/* Sequence preview */}
            {selectedSequence && (
              <div className="rounded-lg border border-border bg-muted/20 px-3 py-2.5 space-y-1.5">
                {selectedSequence.description && (
                  <p className="text-xs text-muted-foreground">
                    {selectedSequence.description}
                  </p>
                )}
                <div className="flex flex-wrap gap-2">
                  {(selectedSequence.sequence_steps ?? []).map((step) => (
                    <div
                      key={step.id}
                      className="flex items-center gap-1 text-xs border border-border rounded-full px-2 py-0.5 bg-background"
                    >
                      <Mail className="h-2.5 w-2.5 text-muted-foreground" />
                      <span className="text-muted-foreground">
                        Day {step.day_offset}:
                      </span>
                      <span className="truncate max-w-[120px]">{step.subject || "—"}</span>
                    </div>
                  ))}
                </div>
                {stepCount > 0 && (
                  <p className="text-xs text-muted-foreground">
                    Total sends:{" "}
                    <span className="font-medium text-foreground">{totalSends}</span>
                    {" "}({stepCount} step{stepCount === 1 ? "" : "s"} ×{" "}
                    {selectedResumeIds.length} candidate
                    {selectedResumeIds.length === 1 ? "" : "s"})
                  </p>
                )}
              </div>
            )}
          </div>

          <DialogFooter className="gap-2">
            <Button
              variant="outline"
              onClick={() => onOpenChange(false)}
              disabled={enroll.isPending}
            >
              Cancel
            </Button>
            <Button
              onClick={handleEnroll}
              disabled={!selectedSequenceId || enroll.isPending || activeSequences.length === 0}
              className="gap-1.5"
            >
              {enroll.isPending ? (
                <Loader2 className="h-4 w-4 animate-spin" />
              ) : (
                <Mail className="h-4 w-4" />
              )}
              {enroll.isPending
                ? "Enrolling…"
                : `Enroll ${selectedResumeIds.length} Candidate${selectedResumeIds.length === 1 ? "" : "s"}`}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Inline sequence creation from within this dialog */}
      <SequenceBuilder
        open={builderOpen}
        onOpenChange={setBuilderOpen}
        onSaved={(id) => {
          setSelectedSequenceId(id);
          setBuilderOpen(false);
        }}
      />
    </>
  );
}

