// ─── Helpers ─────────────────────────────────────────────────────────────────

function formatDate(iso: string | null) {
  if (!iso) return "—";
  return format(parseISO(iso), "MMM d, yyyy");
}

// ─── Status badge ─────────────────────────────────────────────────────────────

function EnrollmentStatusBadge({ status }: { status: SequenceEnrollment["status"] }) {
  const config = {
    active: { label: "Active", className: "bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400" },
    paused: { label: "Paused", className: "bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400" },
    completed: { label: "Completed", className: "bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400" },
    stopped: { label: "Stopped", className: "bg-muted text-muted-foreground" },
  } as const;

  const { label, className } = config[status] ?? config.stopped;
  return (
    <Badge className={`text-[10px] border-0 ${className}`}>{label}</Badge>
  );
}

// ─── Send progress indicator ──────────────────────────────────────────────────

function SendProgress({ sends }: { sends: SequenceEnrollment["sends"] }) {
  if (!sends || sends.length === 0) return <span className="text-xs text-muted-foreground">—</span>;

  const sent = sends.filter((s) => s.status === "sent").length;
  const total = sends.length;

  return (
    <span className="text-xs text-muted-foreground">
      {sent}/{total} sent
    </span>
  );
}

