interface EnrollmentTableProps {
  sequenceId: string;
}

function EnrollmentTable({ sequenceId }: EnrollmentTableProps) {
  const { data: enrollments = [], isLoading } = useEnrollments(sequenceId);
  const updateEnrollment = useUpdateEnrollment();

  async function handleStatusChange(
    enrollment: SequenceEnrollment,
    newStatus: SequenceEnrollment["status"]
  ) {
    try {
      await updateEnrollment.mutateAsync({
        id: enrollment.id,
        sequence_id: sequenceId,
        status: newStatus,
      });
      const labels: Record<SequenceEnrollment["status"], string> = {
        active: "Resumed",
        paused: "Paused",
        completed: "Completed",
        stopped: "Stopped",
      };
      toast.success(`${labels[newStatus]} for ${enrollment.candidate_name ?? "candidate"}`);
    } catch {
      toast.error("Failed to update enrollment");
    }
  }

  if (isLoading) {
    return (
      <div className="space-y-2 py-4">
        {[1, 2, 3].map((i) => (
          <div key={i} className="flex items-center gap-3">
            <Skeleton className="h-4 flex-1" />
            <Skeleton className="h-4 w-20" />
            <Skeleton className="h-4 w-16" />
          </div>
        ))}
      </div>
    );
  }

  if (enrollments.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-12 text-center">
        <div className="rounded-xl bg-muted/50 p-3 mb-3">
          <Users className="h-6 w-6 text-muted-foreground/40" />
        </div>
        <p className="text-sm font-medium">No candidates enrolled</p>
        <p className="text-xs text-muted-foreground mt-1 max-w-xs">
          Select candidates from a job's results page and use "Add to Sequence" to enroll them.
        </p>
      </div>
    );
  }

  return (
    <Table>
      <TableHeader>
        <TableRow>
          <TableHead className="text-xs">Candidate</TableHead>
          <TableHead className="text-xs">Job</TableHead>
          <TableHead className="text-xs">Status</TableHead>
          <TableHead className="text-xs">Progress</TableHead>
          <TableHead className="text-xs">Enrolled</TableHead>
          <TableHead className="w-10" />
        </TableRow>
      </TableHeader>
      <TableBody>
        {enrollments.map((enrollment) => (
          <TableRow key={enrollment.id}>
            <TableCell className="py-2">
              <div>
                <p className="text-sm font-medium">
                  {enrollment.candidate_name ?? "Unknown"}
                </p>
                {enrollment.candidate_email && (
                  <p className="text-xs text-muted-foreground">
                    {enrollment.candidate_email}
                  </p>
                )}
              </div>
            </TableCell>
            <TableCell className="py-2 text-sm text-muted-foreground">
              {enrollment.job_title ?? "—"}
            </TableCell>
            <TableCell className="py-2">
              <EnrollmentStatusBadge status={enrollment.status} />
            </TableCell>
            <TableCell className="py-2">
              <SendProgress sends={enrollment.sends} />
            </TableCell>
            <TableCell className="py-2 text-xs text-muted-foreground">
              {formatDate(enrollment.enrolled_at)}
            </TableCell>
            <TableCell className="py-2">
              {(enrollment.status === "active" || enrollment.status === "paused") && (
                <DropdownMenu>
                  <DropdownMenuTrigger asChild>
                    <Button variant="ghost" size="icon" className="h-7 w-7">
                      <MoreHorizontal className="h-3.5 w-3.5" />
                    </Button>
                  </DropdownMenuTrigger>
                  <DropdownMenuContent align="end">
                    {enrollment.status === "active" ? (
                      <DropdownMenuItem
                        onClick={() => handleStatusChange(enrollment, "paused")}
                      >
                        <Pause className="h-3.5 w-3.5 mr-2" />
                        Pause
                      </DropdownMenuItem>
                    ) : (
                      <DropdownMenuItem
                        onClick={() => handleStatusChange(enrollment, "active")}
                      >
                        <Play className="h-3.5 w-3.5 mr-2" />
                        Resume
                      </DropdownMenuItem>
                    )}
                    <DropdownMenuSeparator />
                    <DropdownMenuItem
                      className="text-destructive focus:text-destructive"
                      onClick={() => handleStatusChange(enrollment, "stopped")}
                    >
                      <SkipForward className="h-3.5 w-3.5 mr-2" />
                      Stop
                    </DropdownMenuItem>
                  </DropdownMenuContent>
                </DropdownMenu>
              )}
            </TableCell>
          </TableRow>
        ))}
      </TableBody>
    </Table>
  );
}

// ─── Sequence card ────────────────────────────────────────────────────────────

interface SequenceCardProps {
  sequence: Sequence;
  onEdit: (id: string) => void;
  onDelete: (id: string) => void;
  onToggleActive: (id: string, current: boolean) => void;
  onClick: (id: string) => void;
}

function SequenceCard({
  sequence,
  onEdit,
  onDelete,
  onToggleActive,
  onClick,
}: SequenceCardProps) {
  return (
    <Card
      className="border border-border/60 shadow-sm hover:shadow-md transition-shadow cursor-pointer group"
      onClick={() => onClick(sequence.id)}
    >
      <CardHeader className="pb-2">
        <div className="flex items-start justify-between gap-2">
          <div className="flex items-center gap-2 min-w-0">
            <div
              className={`h-2 w-2 rounded-full shrink-0 ${
                sequence.is_active ? "bg-green-500" : "bg-muted-foreground/40"
              }`}
            />
            <CardTitle className="text-sm font-semibold truncate">
              {sequence.name}
            </CardTitle>
          </div>
          <DropdownMenu>
            <DropdownMenuTrigger asChild onClick={(e) => e.stopPropagation()}>
              <Button
                variant="ghost"
                size="icon"
                className="h-7 w-7 opacity-0 group-hover:opacity-100 transition-opacity shrink-0"
              >
                <MoreHorizontal className="h-3.5 w-3.5" />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end">
              <DropdownMenuItem
                onClick={(e) => {
                  e.stopPropagation();
                  onEdit(sequence.id);
                }}
              >
                <Pencil className="h-3.5 w-3.5 mr-2" />
                Edit
              </DropdownMenuItem>
              <DropdownMenuItem
                onClick={(e) => {
                  e.stopPropagation();
                  onToggleActive(sequence.id, sequence.is_active);
                }}
              >
                {sequence.is_active ? (
                  <>
                    <Pause className="h-3.5 w-3.5 mr-2" />
                    Deactivate
                  </>
                ) : (
                  <>
                    <Play className="h-3.5 w-3.5 mr-2" />
                    Activate
                  </>
                )}
              </DropdownMenuItem>
              <DropdownMenuSeparator />
              <DropdownMenuItem
                className="text-destructive focus:text-destructive"
                onClick={(e) => {
                  e.stopPropagation();
                  onDelete(sequence.id);
                }}
              >
                <Trash2 className="h-3.5 w-3.5 mr-2" />
                Delete
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
        {sequence.description && (
          <CardDescription className="text-xs line-clamp-2 mt-1">
            {sequence.description}
          </CardDescription>
        )}
      </CardHeader>

      <CardContent className="pt-0">
        <div className="flex items-center gap-3 text-xs text-muted-foreground">
          <div className="flex items-center gap-1">
            <Mail className="h-3 w-3" />
            <span>—</span>
          </div>
          <div className="flex items-center gap-1">
            <Users className="h-3 w-3" />
            <span>{sequence.enrollment_count ?? 0} enrolled</span>
          </div>
          <div className="flex items-center gap-1 ml-auto">
            <Clock className="h-3 w-3" />
            <span>{formatDate(sequence.created_at)}</span>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

// ─── Sequence detail view ─────────────────────────────────────────────────────

interface SequenceDetailViewProps {
  sequenceId: string;
  onBack: () => void;
  onEdit: (id: string) => void;
}

function SequenceDetailView({ sequenceId, onBack, onEdit }: SequenceDetailViewProps) {
  const { data: sequence, isLoading } = useSequence(sequenceId);

  if (isLoading) {
    return (
      <div className="space-y-4">
        <Skeleton className="h-7 w-48" />
        <Skeleton className="h-4 w-72" />
        <div className="grid grid-cols-3 gap-4 mt-6">
          {[1, 2, 3].map((i) => <Skeleton key={i} className="h-16 rounded-lg" />)}
        </div>
      </div>
    );
  }

  if (!sequence) {
    return (
      <div className="flex flex-col items-center justify-center py-16 text-center">
        <AlertCircle className="h-8 w-8 text-muted-foreground/40 mb-3" />
        <p className="text-sm font-medium">Sequence not found</p>
      </div>
    );
  }

  const steps = sequence.sequence_steps ?? [];

  return (
    <div className="space-y-6">
      {/* Back button + header */}
      <div>
        <Button
          variant="ghost"
          size="sm"
          onClick={onBack}
          className="gap-1.5 text-muted-foreground -ml-2 mb-3"
        >
          <ChevronLeft className="h-4 w-4" />
          All Sequences
        </Button>

        <div className="flex items-start justify-between gap-4">
          <div>
            <div className="flex items-center gap-2">
              <h2 className="text-xl font-bold">{sequence.name}</h2>
              <Badge
                className={
                  sequence.is_active
                    ? "bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400 border-0"
                    : "bg-muted text-muted-foreground border-0"
                }
              >
                {sequence.is_active ? "Active" : "Inactive"}
              </Badge>
            </div>
            {sequence.description && (
              <p className="text-sm text-muted-foreground mt-1">{sequence.description}</p>
            )}
          </div>
          <Button
            variant="outline"
            size="sm"
            onClick={() => onEdit(sequenceId)}
            className="gap-1.5 shrink-0"
          >
            <Pencil className="h-3.5 w-3.5" />
            Edit
          </Button>
        </div>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-3 gap-3">
        <div className="rounded-lg border border-border bg-card px-4 py-3">
          <p className="text-xs text-muted-foreground mb-0.5">Steps</p>
          <p className="text-2xl font-bold">{steps.length}</p>
        </div>
        <div className="rounded-lg border border-border bg-card px-4 py-3">
          <p className="text-xs text-muted-foreground mb-0.5">Duration</p>
          <p className="text-2xl font-bold">
            {steps.length === 0
              ? "—"
              : `${Math.max(...steps.map((s) => s.day_offset))}d`}
          </p>
        </div>
        <div className="rounded-lg border border-border bg-card px-4 py-3">
          <p className="text-xs text-muted-foreground mb-0.5">Total Enrolled</p>
          <p className="text-2xl font-bold">{sequence.enrollment_count ?? 0}</p>
        </div>
      </div>

      <Tabs defaultValue="enrollments">
        <TabsList>
          <TabsTrigger value="enrollments">Enrollments</TabsTrigger>
          <TabsTrigger value="steps">Steps ({steps.length})</TabsTrigger>
        </TabsList>

        <TabsContent value="enrollments" className="mt-4">
          <Card className="border border-border/60 shadow-sm">
            <CardContent className="p-0">
              <EnrollmentTable sequenceId={sequenceId} />
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="steps" className="mt-4">
          {steps.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-12 text-center">
              <Mail className="h-8 w-8 text-muted-foreground/30 mb-3" />
              <p className="text-sm font-medium">No steps configured</p>
              <Button
                size="sm"
                variant="outline"
                onClick={() => onEdit(sequenceId)}
                className="mt-3 gap-1.5"
              >
                <Pencil className="h-3.5 w-3.5" />
                Edit Sequence
              </Button>
            </div>
          ) : (
            <div className="space-y-2">
              {steps.map((step) => (
                <Card key={step.id} className="border border-border/60 shadow-sm">
                  <CardContent className="py-3 px-4">
                    <div className="flex items-start gap-3">
                      <div className="flex flex-col items-center gap-1 shrink-0 pt-0.5">
                        <div className="h-6 w-6 rounded-full bg-primary/10 text-primary flex items-center justify-center text-[11px] font-semibold">
                          {step.step_order}
                        </div>
                        <div className="flex items-center gap-1 text-[10px] text-muted-foreground">
                          <Clock className="h-2.5 w-2.5" />
                          <span>D{step.day_offset}</span>
                        </div>
                      </div>
                      <div className="flex-1 min-w-0">
                        <p className="text-sm font-medium">{step.subject}</p>
                        <p className="text-xs text-muted-foreground mt-0.5 line-clamp-2">
                          {step.body}
                        </p>
                      </div>
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          )}
        </TabsContent>
      </Tabs>
    </div>
  );
}

// ─── Main page ────────────────────────────────────────────────────────────────

const Sequences = () => {
  const { data: sequences = [], isLoading, error } = useSequences();
  const deleteSequence = useDeleteSequence();
  const updateSequence = useUpdateSequence();

  const [builderOpen, setBuilderOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [deleteConfirm, setDeleteConfirm] = useState<string | null>(null);
  const [selectedId, setSelectedId] = useState<string | null>(null);

  async function handleDelete(id: string) {
    try {
      await deleteSequence.mutateAsync(id);
      toast.success("Sequence deleted");
      if (selectedId === id) setSelectedId(null);
    } catch {
      toast.error("Failed to delete sequence");
    } finally {
      setDeleteConfirm(null);
    }
  }

  async function handleToggleActive(id: string, current: boolean) {
    try {
      await updateSequence.mutateAsync({ id, is_active: !current });
      toast.success(current ? "Sequence deactivated" : "Sequence activated");
    } catch {
      toast.error("Failed to update sequence");
    }
  }

  function openEdit(id: string) {
    setEditingId(id);
    setBuilderOpen(true);
  }

  return (
    <SidebarLayout>
      <main className="w-full px-6 sm:px-8 lg:px-10 py-8">
        {/* Page header */}
        {!selectedId && (
          <>
            <div className="flex items-center justify-between mb-1">
              <div>
                <h1 className="text-2xl font-bold text-foreground">
                  Email Sequences
                </h1>
              </div>
              <Button
                size="sm"
                onClick={() => { setEditingId(null); setBuilderOpen(true); }}
                className="gap-1.5"
              >
                <Plus className="h-4 w-4" />
                New Sequence
              </Button>
            </div>
            <p className="text-sm text-muted-foreground mb-6">
              Automate candidate outreach with multi-step drip campaigns.
            </p>
          </>
        )}

        {/* Loading */}
        {isLoading && !selectedId && (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
            {[1, 2, 3].map((i) => (
              <Card key={i} className="border border-border/60 shadow-sm">
                <CardHeader className="pb-2">
                  <Skeleton className="h-4 w-32" />
                  <Skeleton className="h-3 w-48 mt-1.5" />
                </CardHeader>
                <CardContent className="pt-0">
                  <Skeleton className="h-3 w-full" />
                </CardContent>
              </Card>
            ))}
          </div>
        )}

        {/* Error */}
        {!isLoading && error && !selectedId && (
          <div className="flex flex-col items-center justify-center py-12 text-center">
            <AlertCircle className="h-8 w-8 text-muted-foreground/40 mb-3" />
            <p className="text-sm font-medium">Failed to load sequences</p>
            <p className="text-xs text-muted-foreground mt-1">Please refresh the page</p>
          </div>
        )}

        {/* Detail view */}
        {selectedId && (
          <SequenceDetailView
            sequenceId={selectedId}
            onBack={() => setSelectedId(null)}
            onEdit={openEdit}
          />
        )}

        {/* List view */}
        {!selectedId && !isLoading && !error && (
          <>
            {sequences.length === 0 ? (
              <div className="flex flex-col items-center justify-center py-16 space-y-4 text-center">
                <div className="rounded-xl bg-muted/50 p-4">
                  <Mail className="h-7 w-7 text-muted-foreground/50" />
                </div>
                <div className="space-y-1">
                  <p className="text-sm font-medium">No sequences yet</p>
                  <p className="text-sm text-muted-foreground max-w-xs">
                    Create your first email sequence to automate candidate outreach.
                  </p>
                </div>
                <Button
                  size="sm"
                  onClick={() => { setEditingId(null); setBuilderOpen(true); }}
                  className="gap-1.5"
                >
                  <Plus className="h-4 w-4" />
                  Create Sequence
                </Button>
              </div>
            ) : (
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                {sequences.map((seq) => (
                  <SequenceCard
                    key={seq.id}
                    sequence={seq}
                    onEdit={openEdit}
                    onDelete={(id) => setDeleteConfirm(id)}
                    onToggleActive={handleToggleActive}
                    onClick={setSelectedId}
                  />
                ))}
              </div>
            )}
          </>
        )}
      </main>

      {/* Sequence builder dialog */}
      <SequenceBuilder
        open={builderOpen}
        onOpenChange={(open) => {
          setBuilderOpen(open);
          if (!open) setEditingId(null);
        }}
        sequenceId={editingId}
        onSaved={(id) => {
          if (editingId) setSelectedId(id);
        }}
      />

      {/* Delete confirmation */}
      <AlertDialog
        open={!!deleteConfirm}
        onOpenChange={(open) => !open && setDeleteConfirm(null)}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete sequence?</AlertDialogTitle>
            <AlertDialogDescription>
              This will permanently delete the sequence, all its steps, and all
              enrollment records. Emails already sent are not affected.
              This cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => deleteConfirm && handleDelete(deleteConfirm)}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </SidebarLayout>
  );
};

export default Sequences;

