import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
import { Switch } from "@/components/ui/switch";
// ─── Email Sequences ──────────────────────────────────────────────────────────
import { EnrollInSequenceDialog } from "@/components/EnrollInSequenceDialog";

// ─── Job Metadata (for career page) ─────────────────────────────────────────

const [blindMode, setBlindMode] = useState(false);
// ── Email Sequences ───────────────────────────────────────────────────────
const [enrollDialogOpen, setEnrollDialogOpen] = useState(false);

{/* Row 2: Selection actions — only when candidates are selected */}
{selectedResumes.size > 0 && (
  <div className="flex items-center gap-2 px-3 py-2 rounded-lg bg-muted/50 border border-border">
    <span className="text-xs font-medium text-foreground">{selectedResumes.size} selected</span>
    <div className="flex items-center gap-1.5 ml-auto">
      <Button variant="outline" size="sm" className="h-7 text-xs" onClick={() => setSelectedResumes(new Set())}>
        Clear
      </Button>
      {/* ── Add to Sequence (email drip campaigns) ─────────────────────── */}
      <Button
        variant="outline"
        size="sm"
        className="h-7 gap-1.5 text-xs"
        onClick={() => setEnrollDialogOpen(true)}
      >
        <Mail className="h-3 w-3" />
        Add to Sequence
      </Button>
      <Button variant="destructive" size="sm" className="h-7 gap-1.5 text-xs" onClick={() => setDeleteConfirm({ type: "bulk" })}>
        <Trash2 className="h-3 w-3" /> Delete
      </Button>
    </div>
  </div>
)}
{/* EnrollInSequenceDialog — rendered outside the button row to avoid layout issues */}
{selectedJobId && (
  <EnrollInSequenceDialog
    open={enrollDialogOpen}
    onOpenChange={setEnrollDialogOpen}
    selectedResumeIds={Array.from(selectedResumes)}
    jobId={selectedJobId}
  />
)}
